// ─── File: SagaDemo.java ───
// Runnable demo. Shows a Saga (local tx per step + compensation) and the
// Outbox pattern instead of JTA/XA two-phase commit. Eventual consistency.

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class SagaDemo {
    private static final Logger log = Logger.getLogger("BankSaga");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AccountRepository repo = new AccountRepository();
        OutboxRepository outbox = new OutboxRepository();
        AccountService accounts = new AccountService(repo, outbox, log);
        TransferSaga saga = new TransferSaga(accounts, log);
        OutboxRelay relay = new OutboxRelay(outbox, log);

        log.info(() -> "=== Successful Saga ===");
        saga.transfer("SAV2001", "CUR3001", new BigDecimal("50000"));
        relay.publishPending();  // later, out of band -> eventual consistency

        log.info(() -> "=== Failing Saga (credit step fails) ===");
        saga.transfer("SAV2001", "FROZEN9", new BigDecimal("30000")); // target invalid
        relay.publishPending();

        log.info(() -> "FINAL Rajesh = " + repo.findById("SAV2001").getBalance());
    }
}

// ─── model/Account.java ───
class Account {
    private final String accountId; private final String holderName; private BigDecimal balance;
    Account(String id, String name, BigDecimal bal) { accountId=id; holderName=name; balance=bal; }
    String getAccountId() { return accountId; }
    BigDecimal getBalance() { return balance; }
    void debit(BigDecimal a) { balance = balance.subtract(a); }
    void credit(BigDecimal a) { balance = balance.add(a); }
}

// ─── model/OutboxEvent.java ───
class OutboxEvent {
    final long id; final String aggregate; final String payload; boolean sent;
    OutboxEvent(long id, String aggregate, String payload) {
        this.id=id; this.aggregate=aggregate; this.payload=payload; this.sent=false;
    }
}

// ─── repository/AccountRepository.java ───
class AccountRepository {
    private final Map<String, Account> store = new HashMap<>();
    AccountRepository() {
        store.put("SAV2001", new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000")));
        store.put("CUR3001", new Account("CUR3001", "Priya Sharma", new BigDecimal("250000")));
    }
    Account findById(String id) { return store.get(id); } // null for invalid target
    void save(Account a) { store.put(a.getAccountId(), a); }
}

// ─── repository/OutboxRepository.java ───
class OutboxRepository {
    private final List<OutboxEvent> rows = new ArrayList<>();
    private long seq = 0;
    OutboxEvent add(String aggregate, String payload) {
        OutboxEvent e = new OutboxEvent(++seq, aggregate, payload);
        rows.add(e); return e;
    }
    List<OutboxEvent> unsent() {
        List<OutboxEvent> out = new ArrayList<>();
        for (OutboxEvent e : rows) if (!e.sent) out.add(e);
        return out;
    }
}

// ─── service/AccountService.java ───
// Each method is ONE LOCAL @Transactional on a SINGLE database.
// No XA, no two-phase commit.
class AccountService {
    private final AccountRepository repo; private final OutboxRepository outbox; private final Logger log;
    AccountService(AccountRepository repo, OutboxRepository outbox, Logger log) {
        this.repo=repo; this.outbox=outbox; this.log=log;
    }
    // @Transactional — business write + outbox insert in the SAME local tx
    void debit(String id, BigDecimal amount) {
        Account a = repo.findById(id);
        if (a == null) throw new RuntimeException("Account not found: " + id);
        if (a.getBalance().compareTo(amount) < 0) throw new RuntimeException("Insufficient: " + id);
        a.debit(amount);
        repo.save(a);
        outbox.add("transfer", "DEBITED " + id + " Rs." + amount);  // atomic with debit
        log.info(() -> "[LOCAL COMMIT] debit " + id + " Rs." + amount);
    }
    // @Transactional — single local tx
    void credit(String id, BigDecimal amount) {
        Account a = repo.findById(id);
        if (a == null) throw new RuntimeException("Account not found: " + id);
        a.credit(amount);
        repo.save(a);
        outbox.add("transfer", "CREDITED " + id + " Rs." + amount);
        log.info(() -> "[LOCAL COMMIT] credit " + id + " Rs." + amount);
    }
    // Compensating transaction — undo a debit
    void compensateDebit(String id, BigDecimal amount) {
        Account a = repo.findById(id);
        a.credit(amount);
        repo.save(a);
        log.warning(() -> "[COMPENSATE] refunded " + id + " Rs." + amount);
    }
}

// ─── orchestrator/TransferSaga.java ───
// Orchestration Saga: runs steps, compensates on failure. No global lock.
class TransferSaga {
    private final AccountService accounts; private final Logger log;
    TransferSaga(AccountService accounts, Logger log) { this.accounts=accounts; this.log=log; }
    void transfer(String from, String to, BigDecimal amount) {
        // Step 1: debit (local commit)
        accounts.debit(from, amount);
        try {
            // Step 2: credit (local commit) — may fail
            accounts.credit(to, amount);
            log.info(() -> "Saga COMPLETE " + from + "->" + to + " Rs." + amount);
        } catch (RuntimeException ex) {
            // Compensation: undo step 1
            log.severe(() -> "Saga step 2 failed: " + ex.getMessage() + " -> compensating");
            accounts.compensateDebit(from, amount);
            log.info(() -> "Saga COMPENSATED, system consistent again");
        }
    }
}

// ─── service/OutboxRelay.java ───
// Separate process: reads unsent outbox rows and publishes to Kafka later.
// This is why we get EVENTUAL consistency, not instant.
class OutboxRelay {
    private final OutboxRepository outbox; private final Logger log;
    OutboxRelay(OutboxRepository outbox, Logger log) { this.outbox=outbox; this.log=log; }
    void publishPending() {
        for (OutboxEvent e : outbox.unsent()) {
            log.info(() -> "[RELAY->Kafka] " + e.payload);  // at-least-once publish
            e.sent = true;
        }
    }
}

// ─── Clean log formatter ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$-7s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel().getName(), r.getMessage());
    }
}
